let audioCtx;
        let oscL, oscR, gainR;
        let masterGain;
        let isPlaying = false;
        let currentPhase = 'in';
        let currentFreq = 440;
        function initAudio() {
            if (!audioCtx) {
                audioCtx = new (window.AudioContext || window.webkitAudioContext)();
                masterGain = audioCtx.createGain();
                masterGain.connect(audioCtx.destination);
                masterGain.gain.setValueAtTime(0.3, audioCtx.currentTime);
            }
        }
        function toggleAudio() {
            initAudio();
            const btn = document.getElementById('main-btn');
            const icon = document.getElementById('btn-icon');
            const text = document.getElementById('btn-text');
            const status = document.getElementById('status-text');
            if (isPlaying) {
                stopOsc();
                icon.innerHTML = `<path fill-rule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zM9.555 7.168A1 1 0 008 8v4a1 1 0 001.555.832l3-2a1 1 0 000-1.664l-3-2z" clip-rule="evenodd"></path>`;
                text.innerText = "INITIALIZE ANALOG SIGNAL";
                btn.classList.replace('bg-red-600', 'bg-slate-900');
                btn.classList.replace('hover:bg-red-500', 'hover:bg-black');
                status.innerText = "ENGINE IDLE";
                updateMeter(0);
            } else {
                startOsc();
                icon.innerHTML = `<path fill-rule="evenodd" d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zM7 8a1 1 0 012 0v4a1 1 0 11-2 0V8zm5-1a1 1 0 00-1 1v4a1 1 0 102 0V8a1 1 0 00-1-1z" clip-rule="evenodd"></path>`;
                text.innerText = "HALT SIGNAL GENERATOR";
                btn.classList.replace('bg-slate-900', 'bg-red-600');
                btn.classList.replace('hover:bg-black', 'hover:bg-red-500');
                status.innerText = "SIGNAL BROADCASTING";
                setPhase(currentPhase);
            }
            isPlaying = !isPlaying;
        }
        function startOsc() {
            const merger = audioCtx.createChannelMerger(2);
            oscL = audioCtx.createOscillator();
            oscR = audioCtx.createOscillator();
            gainR = audioCtx.createGain();
            oscL.type = 'sine';
            oscR.type = 'sine';
            oscL.frequency.setValueAtTime(currentFreq, audioCtx.currentTime);
            oscR.frequency.setValueAtTime(currentFreq, audioCtx.currentTime);
            oscL.connect(merger, 0, 0);
            oscR.connect(gainR);
            gainR.connect(merger, 0, 1);
            merger.connect(masterGain);
            oscL.start();
            oscR.start();
        }
        function stopOsc() {
            if (oscL) {
                oscL.stop();
                oscL.disconnect();
            }
            if (oscR) {
                oscR.stop();
                oscR.disconnect();
            }
        }
        function setPhase(type) {
            currentPhase = type;
            document.getElementById('btn-in').classList.remove('active-in');
            document.getElementById('btn-out').classList.remove('active-out');
            if (type === 'in') {
                if (gainR && audioCtx) gainR.gain.setTargetAtTime(1, audioCtx.currentTime, 0.01);
                document.getElementById('btn-in').classList.add('active-in');
                if (isPlaying) updateMeter(1);
            } else {
                if (gainR && audioCtx) gainR.gain.setTargetAtTime(-1, audioCtx.currentTime, 0.01);
                document.getElementById('btn-out').classList.add('active-out');
                if (isPlaying) updateMeter(-1);
            }
        }
        function setFreq(hz) {
            currentFreq = hz;
            document.querySelectorAll('.freq-btn').forEach(b => b.classList.remove('active'));
            document.getElementById(`f-${hz}`).classList.add('active');
            if (oscL && oscR && audioCtx) {
                oscL.frequency.setTargetAtTime(hz, audioCtx.currentTime, 0.05);
                oscR.frequency.setTargetAtTime(hz, audioCtx.currentTime, 0.05);
            }
        }
        function updateMeter(val) {
            const pointer = document.getElementById('meter-pointer');
            // Logic: -1 to +1 map to 0 to 100%
            const pct = ((val + 1) / 2) * 100;
            pointer.style.left = `calc(${pct}% - 2px)`;
        }
        // --- GLOBAL SCROLL LOGIC ---
